// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/*
 *   ____            _               _ _
 *  / __ \          | |             | | |
 * | |  | |_ __ ___ | |__  _ __ ___ | | | ___
 * | |  | | '_ ` _ \| '_ \| '__/ _ \| | |/ _ \
 * | |__| | | | | | | |_) | | |  __/| | | (_) |
 *  \____/|_| |_| |_|_.__/|_|  \___||_|_|\___/
 *
 * Ombrello (OMB) - 1,111 ERC-721 pieces on BNB Smart Chain.
 *
 * Key properties
 *  - Random token IDs on every mint (anti-sniping), no repeats, flat gas.
 *  - Two phases: allowlist (Merkle) and agent/public, each with its own
 *    price, per-wallet limit, start/end time and manual on/off switch.
 *  - Native BNB only. Exact payment required (wrong amounts revert).
 *  - onlyEOA on by default; _mint (no receiver callback) to stop re-roll bots.
 *  - Agent-only: WL and agent mints require a .ai Agent ID (on BNB mainnet the
 *    registry is set automatically at deploy).
 *  - Ownership can't be renounced; transfer is two-step.
 *  - Transfers locked at deploy; owner can unlock once, never re-lock.
 *  - One-way switches: unlockTransfers, closeSupply, freezeMetadata.
 *  - No proxy, no upgrade path, no owner power over holders' tokens.
 */

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

/// @notice .ai Agent ID registry (SPACE ID "Agent ID", symbol AI). Soulbound ERC721, one per address.
interface IAgentIdRegistry {
    function balanceOf(address owner) external view returns (uint256);
}

contract Ombrello is ERC721, ERC2981, Ownable2Step, Pausable, ReentrancyGuard {
    using Strings for uint256;

    // ---------------------------------------------------------------------
    // Types
    // ---------------------------------------------------------------------

    /// @notice None = no phase open, WL = allowlist phase, Public = agent/public phase.
    enum Phase {
        None,
        WL,
        Public
    }

    /// @dev Packed into two storage slots.
    struct PhaseConfig {
        uint128 price; // price per token in wei (BNB)
        uint32 maxPerWallet; // max tokens one wallet may mint in this phase
        bool active; // manual on/off switch
        bool priceSet; // public phase must have a price set before opening
        uint64 startTime; // unix seconds (UTC); 0 = no start restriction
        uint64 endTime; // unix seconds (UTC); 0 = no end restriction
    }

    // ---------------------------------------------------------------------
    // Constants / immutables
    // ---------------------------------------------------------------------

    /// @notice Size of the original ID pool. Token IDs are 1..POOL_SIZE.
    uint256 public constant POOL_SIZE = 1111;

    /// @notice Hard maximum royalty: 10% (1000 basis points).
    uint96 public constant MAX_ROYALTY_BPS = 1000;

    /// @notice Max tokens the owner may mint through ownerMint (counted inside the supply).
    uint256 public immutable reserveCap;

    // ---------------------------------------------------------------------
    // Supply state
    // ---------------------------------------------------------------------

    /// @notice Current max supply. Starts at POOL_SIZE; can only go DOWN (closeSupply).
    uint256 public maxSupply = POOL_SIZE;

    /// @notice Tokens ever minted (burns do NOT reduce this). Drives all supply math.
    uint256 public totalMinted;

    /// @notice Tokens burned by holders.
    uint256 public totalBurned;

    /// @notice Tokens minted through ownerMint.
    uint256 public reserveMinted;

    bool public supplyClosed;

    /// @dev Fisher-Yates "virtual array" for random IDs.
    ///      _idSwap[i] == 0 means slot i still holds its own value i.
    ///      Values stored are (index + 1) so that 0 can mean "untouched".
    mapping(uint256 => uint256) private _idSwap;

    /// @dev Running nonce mixed into randomness.
    uint256 private _randNonce;

    // ---------------------------------------------------------------------
    // Phase state
    // ---------------------------------------------------------------------

    mapping(Phase => PhaseConfig) private _phase;
    bytes32 public merkleRoot;

    /// @dev wallet => phase => minted count
    mapping(address => mapping(Phase => uint256)) private _mintedBy;

    /// @notice If true, only externally-owned accounts (tx.origin == msg.sender) can mint.
    ///         ON by default (set in the constructor); owner can toggle it.
    bool public onlyEOA;

    // ---------------------------------------------------------------------
    // Agent ID gate
    // ---------------------------------------------------------------------

    /// @notice .ai Agent ID registry on BNB Chain mainnet (chain 56).
    address public constant MAINNET_AGENT_REGISTRY = 0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F;

    /// @notice Registry checked on every WL and agent mint (balanceOf(minter) > 0).
    ///         address(0) = gate off. Set automatically on mainnet at deploy.
    IAgentIdRegistry public agentRegistry;

    // ---------------------------------------------------------------------
    // Transfer lock / burn
    // ---------------------------------------------------------------------

    bool private _transfersLocked = true;
    bool public burnEnabled;

    // ---------------------------------------------------------------------
    // Metadata
    // ---------------------------------------------------------------------

    string private _baseTokenURI;
    string public placeholderURI;
    bool public placeholderEnabled;
    bool public metadataFrozen;

    // ---------------------------------------------------------------------
    // Events
    // ---------------------------------------------------------------------

    event Minted(address indexed to, uint256 indexed tokenId, Phase indexed phase);
    event ReserveMinted(address indexed to, uint256 quantity);
    event PriceUpdated(Phase indexed phase, uint256 price);
    event MaxPerWalletUpdated(Phase indexed phase, uint256 maxPerWallet);
    event PhaseTimesUpdated(Phase indexed phase, uint64 startTime, uint64 endTime);
    event PhaseActiveUpdated(Phase indexed phase, bool active);
    event MerkleRootUpdated(bytes32 root);
    event OnlyEOAUpdated(bool enabled);
    event BurnEnabledUpdated(bool enabled);
    event BaseURIUpdated(string uri);
    event PlaceholderUpdated(string uri, bool enabled);
    event MetadataFrozen();
    event TransfersUnlocked();
    event SupplyClosed(uint256 finalMaxSupply);
    event RoyaltyUpdated(address indexed receiver, uint96 bps);
    event Withdrawn(address indexed to, uint256 amount);
    event AgentRegistryUpdated(address indexed registry);

    // ---------------------------------------------------------------------
    // Errors
    // ---------------------------------------------------------------------

    error InvalidPhase();
    error PhaseNotOpen();
    error PriceNotSet();
    error WrongPayment(uint256 expected, uint256 sent);
    error ZeroQuantity();
    error ExceedsWalletLimit();
    error ExceedsMaxSupply();
    error ExceedsReserve();
    error NotAllowlisted();
    error NotEOA();
    error TransfersLocked();
    error BurnDisabled();
    error MetadataIsFrozen();
    error PlaceholderStillOn();
    error EmptyBaseURI();
    error SupplyAlreadyClosed();
    error RoyaltyTooHigh();
    error InvalidTimes();
    error NothingToWithdraw();
    error WithdrawFailed();
    error ZeroAddress();
    error RenounceDisabled();
    error NotAgentIdHolder();
    error NotAContract();
    error AgentGateLocked();

    // ---------------------------------------------------------------------
    // Constructor
    // ---------------------------------------------------------------------

    /// @param initialOwner  wallet that will own the contract
    /// @param royaltyReceiver  wallet that receives ERC-2981 royalties (5% default)
    /// @param reserveCap_  max owner mints (use 11 for the default)
    /// @param baseURI_  e.g. "ipfs://<CID>/" (trailing slash!). Can be "" and set later.
    constructor(address initialOwner, address royaltyReceiver, uint256 reserveCap_, string memory baseURI_)
        ERC721("Ombrello", "OMB")
        Ownable(initialOwner)
    {
        if (royaltyReceiver == address(0)) revert ZeroAddress();
        if (reserveCap_ > POOL_SIZE) revert ExceedsReserve();
        reserveCap = reserveCap_;
        _baseTokenURI = baseURI_;

        // WL defaults: free, 1 per wallet. Price counts as "set" (0 is intended).
        _phase[Phase.WL] = PhaseConfig({
            price: 0, maxPerWallet: 1, active: false, priceSet: true, startTime: 0, endTime: 0
        });
        // Public defaults: price UNSET, 2 per wallet.
        _phase[Phase.Public] = PhaseConfig({
            price: 0, maxPerWallet: 2, active: false, priceSet: false, startTime: 0, endTime: 0
        });

        onlyEOA = true; // block contract-based minting by default
        _setDefaultRoyalty(royaltyReceiver, 500); // 5%
        _pause(); // deploy paused

        // Agent-only on BNB mainnet from block one. Testnet starts with the gate off
        // (the registry doesn't exist there); use setAgentRegistry with a test registry.
        if (block.chainid == 56) {
            agentRegistry = IAgentIdRegistry(MAINNET_AGENT_REGISTRY);
            emit AgentRegistryUpdated(MAINNET_AGENT_REGISTRY);
        }
    }

    // =====================================================================
    // Minting
    // =====================================================================

    /// @notice Allowlist mint. `proof` comes from the website / proofs.json.
    function mintWL(uint256 quantity, bytes32[] calldata proof) external payable nonReentrant whenNotPaused {
        if (!_verify(msg.sender, proof)) revert NotAllowlisted();
        _phaseMint(Phase.WL, quantity);
    }

    /// @notice Agent / public mint. Open to anyone while the phase is open.
    function mintPublic(uint256 quantity) external payable nonReentrant whenNotPaused {
        _phaseMint(Phase.Public, quantity);
    }

    /// @notice Owner reserve mint. Random IDs, capped by reserveCap, counted inside maxSupply.
    ///         Works even while paused (useful before launch).
    function ownerMint(address to, uint256 quantity) external onlyOwner nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        if (quantity == 0) revert ZeroQuantity();
        if (reserveMinted + quantity > reserveCap) revert ExceedsReserve();
        if (totalMinted + quantity > maxSupply) revert ExceedsMaxSupply();

        reserveMinted += quantity; // effects first
        emit ReserveMinted(to, quantity);
        for (uint256 i; i < quantity; ++i) {
            _mintRandom(to, Phase.None);
        }
    }

    function _phaseMint(Phase p, uint256 quantity) private {
        if (onlyEOA && tx.origin != msg.sender) revert NotEOA();
        if (!_isAgent(msg.sender)) revert NotAgentIdHolder();
        if (quantity == 0) revert ZeroQuantity();

        PhaseConfig memory c = _phase[p];
        if (!_isOpen(c)) revert PhaseNotOpen();
        if (!c.priceSet) revert PriceNotSet();

        uint256 already = _mintedBy[msg.sender][p];
        if (already + quantity > c.maxPerWallet) revert ExceedsWalletLimit();
        if (totalMinted + quantity > maxSupply) revert ExceedsMaxSupply();

        // Exact payment: wrong amounts revert, so no refund transfer is ever needed.
        uint256 cost = uint256(c.price) * quantity;
        if (msg.value != cost) revert WrongPayment(cost, msg.value);

        _mintedBy[msg.sender][p] = already + quantity; // effects before interactions
        for (uint256 i; i < quantity; ++i) {
            _mintRandom(msg.sender, p);
        }
    }

    /// @dev Picks a random unminted ID with the swap-with-last method and mints it.
    ///
    /// RANDOMNESS - honest note:
    ///  This mixes block.prevrandao, msg.sender, a running nonce and totalMinted.
    ///  It stops simple "mint #723 now" sniping, but it is NOT perfectly random:
    ///  a block producer could influence prevrandao, and a smart contract can
    ///  simulate the outcome in the same transaction and revert if it doesn't
    ///  like the result (turn on onlyEOA to block that). For provably fair
    ///  randomness, upgrade to Chainlink VRF v2.5 on BNB Chain (a two-step
    ///  request/fulfil mint). Not used by default to keep minting simple and cheap.
    function _mintRandom(address to, Phase p) private {
        uint256 left = POOL_SIZE - totalMinted; // IDs still in the pool
        uint256 rand = uint256(
            keccak256(abi.encodePacked(block.prevrandao, msg.sender, to, _randNonce, totalMinted, block.timestamp))
        );
        unchecked {
            ++_randNonce;
        }
        uint256 idx = rand % left;
        uint256 last = left - 1;

        uint256 picked = _valueAt(idx);
        // move the last value into the picked slot, so it stays in the pool
        uint256 lastVal = _valueAt(last);
        if (idx != last) _idSwap[idx] = lastVal + 1;
        if (_idSwap[last] != 0) delete _idSwap[last]; // gas refund, slot is out of range now

        uint256 tokenId = picked + 1; // IDs are 1..1111
        ++totalMinted;
        // _mint (not _safeMint): no onERC721Received callback, so a contract
        // minter cannot inspect its roll and revert to re-roll for a rare.
        _mint(to, tokenId);
        emit Minted(to, tokenId, p);
    }

    function _valueAt(uint256 i) private view returns (uint256) {
        uint256 v = _idSwap[i];
        return v == 0 ? i : v - 1;
    }

    function _isOpen(PhaseConfig memory c) private view returns (bool) {
        if (!c.active) return false;
        if (c.startTime != 0 && block.timestamp < c.startTime) return false;
        if (c.endTime != 0 && block.timestamp >= c.endTime) return false;
        return true;
    }

    /// @dev Leaf format matches OpenZeppelin StandardMerkleTree with ["address"].
    function _verify(address wallet, bytes32[] calldata proof) private view returns (bool) {
        bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(wallet))));
        return MerkleProof.verifyCalldata(proof, merkleRoot, leaf);
    }

    // =====================================================================
    // Holder burn
    // =====================================================================

    /// @notice Token owner (or an approved operator) burns a token. Only while burnEnabled.
    ///         Burns never change totalMinted or maxSupply, so no ID can be minted twice.
    function burn(uint256 tokenId) external {
        if (!burnEnabled) revert BurnDisabled();
        // _update with an auth address checks owner/approval and reverts otherwise.
        _update(address(0), tokenId, _msgSender());
        unchecked {
            ++totalBurned;
        }
    }

    // =====================================================================
    // Owner controls
    // =====================================================================

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function setPrice(Phase p, uint128 priceWei) external onlyOwner {
        _checkPhase(p);
        _phase[p].price = priceWei;
        _phase[p].priceSet = true;
        emit PriceUpdated(p, priceWei);
    }

    function setMaxPerWallet(Phase p, uint32 max) external onlyOwner {
        _checkPhase(p);
        _phase[p].maxPerWallet = max;
        emit MaxPerWalletUpdated(p, max);
    }

    /// @notice 0 means "no limit" for that side. If both set, end must be after start.
    function setPhaseTimes(Phase p, uint64 startTime, uint64 endTime) external onlyOwner {
        _checkPhase(p);
        if (startTime != 0 && endTime != 0 && endTime <= startTime) revert InvalidTimes();
        _phase[p].startTime = startTime;
        _phase[p].endTime = endTime;
        emit PhaseTimesUpdated(p, startTime, endTime);
    }

    function setPhaseActive(Phase p, bool active) external onlyOwner {
        _checkPhase(p);
        if (active && !_phase[p].priceSet) revert PriceNotSet();
        _phase[p].active = active;
        emit PhaseActiveUpdated(p, active);
    }

    function setMerkleRoot(bytes32 root) external onlyOwner {
        merkleRoot = root;
        emit MerkleRootUpdated(root);
    }

    /// @notice Set the Agent ID registry. address(0) turns the gate off.
    function setAgentRegistry(address registry) external onlyOwner {
        if (block.chainid == 56) revert AgentGateLocked();
        if (registry != address(0) && registry.code.length == 0) revert NotAContract();
        agentRegistry = IAgentIdRegistry(registry);
        emit AgentRegistryUpdated(registry);
    }

    function setOnlyEOA(bool enabled) external onlyOwner {
        onlyEOA = enabled;
        emit OnlyEOAUpdated(enabled);
    }

    function setBurnEnabled(bool enabled) external onlyOwner {
        burnEnabled = enabled;
        emit BurnEnabledUpdated(enabled);
    }

    /// @notice ONE-WAY. Transfers can never be locked again.
    function unlockTransfers() external onlyOwner {
        if (!_transfersLocked) return;
        _transfersLocked = false;
        emit TransfersUnlocked();
    }

    /// @notice ONE-WAY. Sets maxSupply to the number minted so far. Nothing can ever be minted again.
    function closeSupply() external onlyOwner {
        if (supplyClosed) revert SupplyAlreadyClosed();
        supplyClosed = true;
        maxSupply = totalMinted;
        emit SupplyClosed(totalMinted);
    }

    /// @param uri e.g. "ipfs://<CID>/" (keep the trailing slash)
    function setBaseURI(string calldata uri) external onlyOwner {
        if (metadataFrozen) revert MetadataIsFrozen();
        _baseTokenURI = uri;
        emit BaseURIUpdated(uri);
    }

    /// @notice Optional "unrevealed" image for all tokens. Off by default.
    function setPlaceholder(string calldata uri, bool enabled) external onlyOwner {
        if (metadataFrozen) revert MetadataIsFrozen();
        placeholderURI = uri;
        placeholderEnabled = enabled;
        emit PlaceholderUpdated(uri, enabled);
    }

    /// @notice ONE-WAY. Locks baseURI forever. Placeholder must be off and baseURI set.
    function freezeMetadata() external onlyOwner {
        if (metadataFrozen) revert MetadataIsFrozen();
        if (placeholderEnabled) revert PlaceholderStillOn();
        if (bytes(_baseTokenURI).length == 0) revert EmptyBaseURI();
        metadataFrozen = true;
        emit MetadataFrozen();
    }

    /// @param bps basis points, 500 = 5%, max 1000 = 10%
    function setRoyalty(address receiver, uint96 bps) external onlyOwner {
        if (receiver == address(0)) revert ZeroAddress();
        if (bps > MAX_ROYALTY_BPS) revert RoyaltyTooHigh();
        _setDefaultRoyalty(receiver, bps);
        emit RoyaltyUpdated(receiver, bps);
    }

    /// @notice Sends all BNB in the contract to the owner.
    function withdraw() external onlyOwner nonReentrant {
        uint256 bal = address(this).balance;
        if (bal == 0) revert NothingToWithdraw();
        address to = owner();
        emit Withdrawn(to, bal);
        (bool ok,) = payable(to).call{value: bal}("");
        if (!ok) revert WithdrawFailed();
    }

    /// @notice Disabled: ownership can never be renounced (lost) by accident.
    ///         Use transferOwnership + acceptOwnership (Ownable2Step) to hand it over.
    function renounceOwnership() public view override onlyOwner {
        revert RenounceDisabled();
    }

    function _checkPhase(Phase p) private pure {
        if (p == Phase.None) revert InvalidPhase();
    }

    // =====================================================================
    // Views (website / agents)
    // =====================================================================

    /// @notice Tokens left to mint under the current maxSupply.
    function remaining() external view returns (uint256) {
        return maxSupply - totalMinted;
    }

    /// @notice Tokens currently in existence (minted - burned).
    function totalSupply() external view returns (uint256) {
        return totalMinted - totalBurned;
    }

    /// @notice Public if open, else WL if open, else None. Ignores pause (check `paused()`).
    function currentPhase() external view returns (Phase) {
        if (_isOpen(_phase[Phase.Public])) return Phase.Public;
        if (_isOpen(_phase[Phase.WL])) return Phase.WL;
        return Phase.None;
    }

    function isPhaseOpen(Phase p) external view returns (bool) {
        if (p == Phase.None) return false;
        return _isOpen(_phase[p]);
    }

    function phaseConfig(Phase p) external view returns (PhaseConfig memory) {
        return _phase[p];
    }

    function phasePrice(Phase p) external view returns (uint256) {
        return _phase[p].price;
    }

    function phaseTimes(Phase p) external view returns (uint64 startTime, uint64 endTime) {
        return (_phase[p].startTime, _phase[p].endTime);
    }

    function maxPerWallet(Phase p) external view returns (uint256) {
        return _phase[p].maxPerWallet;
    }

    function mintedBy(address wallet, Phase p) external view returns (uint256) {
        return _mintedBy[wallet][p];
    }

    /// @notice True if `wallet` may mint under the Agent ID gate (always true when the gate is off).
    function isAgent(address wallet) external view returns (bool) {
        return _isAgent(wallet);
    }

    function _isAgent(address wallet) private view returns (bool) {
        if (address(agentRegistry) == address(0)) return true;
        return agentRegistry.balanceOf(wallet) > 0;
    }

    function isTransfersLocked() external view returns (bool) {
        return _transfersLocked;
    }

    function isOnAllowlist(address wallet, bytes32[] calldata proof) external view returns (bool) {
        return _verify(wallet, proof);
    }

    function baseURI() external view returns (string memory) {
        return _baseTokenURI;
    }

    /// @notice token #N -> baseURI + (N-1) + ".json"  (token #723 -> 722.json)
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        if (placeholderEnabled) return placeholderURI;
        return string.concat(_baseTokenURI, (tokenId - 1).toString(), ".json");
    }

    // =====================================================================
    // Internal overrides
    // =====================================================================

    /// @dev Blocks wallet-to-wallet transfers while locked. Mints (from == 0)
    ///      and burns (to == 0) are allowed. The owner has no bypass.
    function _update(address to, uint256 tokenId, address auth) internal override returns (address) {
        address from = _ownerOf(tokenId);
        if (_transfersLocked && from != address(0) && to != address(0)) revert TransfersLocked();
        return super._update(to, tokenId, auth);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}
